<ol class="onboarding-progress" aria-label="Registration progress"><?php foreach([1=>'Account Details',2=>'Subscription Payment',3=>'Verification'] as $number=>$label): ?><li class="<?= $number<$registrationStep?'is-complete':($number===$registrationStep?'is-current':'') ?>" <?= $number===$registrationStep?'aria-current="step"':'' ?>><span><?= $number<$registrationStep?'✓':$number ?></span><div><small>Step <?= $number ?><?= $number<$registrationStep?' · Completed':'' ?></small><strong><?= e($label) ?></strong></div></li><?php endforeach; ?></ol>
